#include "professional_outcome_read.hpp"
#include "resident/storage/common_store.hpp"
#include <algorithm>
namespace hanmo::resident {namespace {
bool valid(const SourceRef&s){return !s.domain.empty()&&!s.kind.empty()&&!s.id.empty();}
bool same(const SubjectRef&a,const SubjectRef&b){return a.kind==b.kind&&a.id==b.id;}
bool same(const SourceRef&a,const SourceRef&b){return a.domain==b.domain&&a.kind==b.kind&&a.id==b.id;}
const StableId& target_id(const ProfessionalTargetRef&t){return std::visit([](const auto&v)->const StableId&{using T=std::decay_t<decltype(v)>;if constexpr(std::is_same_v<T,ProfessionalActorTarget>)return v.actor_id;else if constexpr(std::is_same_v<T,ProfessionalItemTarget>)return v.instance_id;else if constexpr(std::is_same_v<T,ProfessionalSiteTarget>)return v.site_id;else if constexpr(std::is_same_v<T,ProfessionalWorkTarget>)return v.work_id;else if constexpr(std::is_same_v<T,ProfessionalCaseTarget>)return v.case_id;else if constexpr(std::is_same_v<T,ProfessionalBatchTarget>)return v.batch_id;else if constexpr(std::is_same_v<T,ProfessionalRitualTarget>)return v.ritual_id;else return v.expedition_id;},t);}
}
const char* professional_outcome_kind_name(ProfessionalOutcomeKind k)noexcept{static const char*names[]={"observation_completed","treatment_period_supplied","treatment_closed","medicine_batch_completed","medicine_goods_delivered","research_completed","work_completed","assessment_issued","assessment_corrected","copy_completed","work_delivered","lecture_session_supplied","mediation_contribution_recognized","elixir_batch_completed","talisman_completed","infusion_completed","recharge_completed","effect_maintenance_completed","arcane_appraisal_completed","effect_applied","ritual_completed","expedition_stage_resolved","unique_outcome_awarded"};const auto n=static_cast<Integer>(k);return n>=0&&n<23?names[n]:nullptr;}
const char* professional_outcome_owner(ProfessionalOutcomeKind k)noexcept{const auto n=static_cast<Integer>(k);return n<0||n>=23?nullptr:n<5?"medicine":n<13?"scholarship":"arcana";}
Status validate_outcome_fact_ref(const OutcomeFactRef&r){const char*owner=professional_outcome_owner(r.source_kind);return owner&&r.source_domain==owner&&!r.fact_id.empty()&&r.version>0?common_success():common_failure("UnsupportedOutcomeSchema",r.fact_id,ErrorKind::unsupported_capability);}
bool same_outcome_fact_ref(const OutcomeFactRef&a,const OutcomeFactRef&b){return a.source_domain==b.source_domain&&a.source_kind==b.source_kind&&a.fact_id==b.fact_id&&a.version==b.version;}
bool same_professional_target(const ProfessionalTargetRef&a,const ProfessionalTargetRef&b){return a.index()==b.index()&&target_id(a)==target_id(b);}
Status validate_professional_outcome_view(const ProfessionalOutcomeRead&q,const ProfessionalOutcomeView&v){auto ref=validate_outcome_fact_ref(q.outcome_ref);if(!ref.ok)return ref;if(q.requester_domain!="tasks"||q.objective_ref.empty()||q.expected_criterion_kind.empty()||q.expected_criterion_version.empty()||!q.source_stamp||q.observer.observer.id.empty()||q.observer.registered_scope_ref.empty())return common_failure("InvalidProfessionalOutcomeRead");if(!same_outcome_fact_ref(q.outcome_ref,v.outcome_ref)||!valid(v.source_activity_ref)||v.source_rule_version.empty()||v.settlement_key.empty()||target_id(v.result_target).empty()||v.completed_tick<0||(v.completed_at&&v.completed_tick!=v.completed_at->half_day_tick)||static_cast<Integer>(v.provider_disposition)<0||static_cast<Integer>(v.provider_disposition)>2)return common_failure("ProfessionalOutcomeSourceMismatch",q.outcome_ref.fact_id,ErrorKind::internal);if(v.completed_at){auto at=encode_world_moment(*v.completed_at);if(!at.ok)return {false,{},at.error};}if(v.criterion_kind!=q.expected_criterion_kind||v.criterion_version!=q.expected_criterion_version)return common_failure("CriterionMismatch");if(v.source_terms_ref){auto s=validate_terms_revision(*v.source_terms_ref);if(!s.ok)return s;}if(v.actual_participant.has_value()!=v.participant_contribution_ref.has_value()||(v.actual_participant&&(v.actual_participant->empty()||!valid(*v.participant_contribution_ref))))return common_failure("ProfessionalContributionSourceMismatch",q.outcome_ref.fact_id,ErrorKind::internal);if(q.claimed_participant&&v.actual_participant!=q.claimed_participant)return common_failure("ParticipantNotInOutcome");if(q.claimed_recipient&&(!v.recipient||!same(*q.claimed_recipient,*v.recipient)))return common_failure("RecipientMismatch");if(const auto*m=std::get_if<ProfessionalMeasured>(&v.measure)){if(m->value<0||m->unit_id.empty())return common_failure("InvalidProfessionalMeasure",q.outcome_ref.fact_id,ErrorKind::internal);}else if(!valid(std::get<ProfessionalNonQuantified>(v.measure).predicate_fact_ref))return common_failure("InvalidProfessionalPredicate",q.outcome_ref.fact_id,ErrorKind::internal);for(std::size_t i=0;i<v.relevant_result_refs.size();++i){if(!valid(v.relevant_result_refs[i]))return common_failure("ProfessionalResultSourceMissing");for(std::size_t j=0;j<i;++j)if(same(v.relevant_result_refs[i],v.relevant_result_refs[j]))return common_failure("DuplicateProfessionalResultSource");}for(const auto&ref:v.disclosable_result_refs)if(std::none_of(v.relevant_result_refs.begin(),v.relevant_result_refs.end(),[&](const auto&actual){return same(actual,ref);}))return common_failure("ProfessionalDisclosureSourceMismatch");if(v.supersedes_ref){auto valid=validate_outcome_fact_ref(*v.supersedes_ref);if(!valid.ok)return valid;if(v.supersedes_ref->source_domain!=v.outcome_ref.source_domain||same_outcome_fact_ref(*v.supersedes_ref,v.outcome_ref))return common_failure("InvalidProfessionalSupersedesSource");}return common_success();}
}
